const jsdom = require('jsdom');
const { JSDOM } = jsdom;
const ReportRenderer = require('./path/to/report-renderer');

// Sample report data with missing generatedTime
const sampleResults = {
  reportCategories: [
    { name: 'Performance', score: 0.9 },
    { name: 'Accessibility', score: 0.8 },
  ],
  url: 'http://example.com',
  userAgent: 'Mozilla/5.0',
  // Missing generatedTime
};

// Create a DOM environment
const dom = new JSDOM(`<!DOCTYPE html><body></body>`);
const document = dom.window.document;

// Initialize the renderer
const renderer = new ReportRenderer(document);

// Attempt to render the report
try {
  renderer.renderReport(sampleResults, document.body);
} catch (error) {
  console.error('Error rendering report:', error);
}
